import "./common.tsp";
namespace Sales;
/** An order with recursive related orders and exact native literals. */
@doc("Customer order — preserves Unicode and comments")
model Order extends Entity<string> {
  state: OrderState;
  total: int32 = 42;
  cost: Money;
  related?: Order[];
  externalId?: 9007199254740993;
}
alias OrdersPage = Page<Order>;
union OrderResult { found: Order, absent: NotFound }
interface Orders {
  read(id: string): OrderResult;
  list(): OrdersPage;
}
const retryCount = 3;

files.common.tsp:
// Shared definitions remain distinct source files.
namespace Sales;
@pattern("^[A-Z]{3}$")
scalar CurrencyCode extends string;
model Money { amount: decimal; currency: CurrencyCode; }
model Entity<TId> { @key id: TId; }
model Page<T> { data: T[]; next?: string; }
enum OrderState { pending, shipped, cancelled }
@error model NotFound { message: string; }
